import { GameState, AnalystResponse } from "../../types";
import { AnalystSchema } from "../ai/schemas";
import { ANALYST_INSTRUCTION } from "../ai/prompts";
import { GeminiClient } from "../ai/client";
import { AI_MODELS } from "../ai/config";

export const runAnalyst = async (
  action: string,
  narrative: string,
  currentState: GameState
): Promise<AnalystResponse> => {

  const context = `
  [ESTADO ANTERIOR]:
  Tempo: ${currentState.world.time}
  Local: ${currentState.player.location}
  Inventário: ${currentState.player.inventory.join(", ")}
  Status Jogador: ${currentState.player.status}

  [AÇÃO JOGADOR]: "${action}"
  [NARRATIVA RESULTANTE]: "${narrative}"
  `;

  const prompt = `
  Analise a narrativa acima e extraia as atualizações de estado.
  1. Atualize o mundo (SQLite).
  2. Extraia conexões lógicas (Graph).
  3. Prepare metadados de memória (Chroma).
  `;

  // Modelo FAST é suficiente pois é uma tarefa de extração lógica, não criativa.
  return GeminiClient.generateStructured<AnalystResponse>(
    AI_MODELS.FAST,
    context + "\n" + prompt,
    AnalystSchema,
    ANALYST_INSTRUCTION
  );
};

import { GraphEdge } from "../../types";
import { apiClient } from "./core";

// Payload unificado para envio aos 3 bancos de dados
export interface UnifiedIngestPayload {
  userId: string;
  universeId: string;
  turnId: number;
  timestamp: string; 

  // Chroma DB
  vectorData: {
    text: string;
    type: 'turn' | 'lore' | 'intro';
    location: string;
    // [NEW] Metadata otimizado vindo do Analyst Agent
    keywords?: string[];
    summary?: string;
    importance?: string;
  };

  // SQLite Logs
  sqlData: {
    playerStatus: any;
    inventory: string[];
    worldState: any;
  };

  // Neo4j Graph (Frontend usa source/target, Backend espera subject/object)
  graphData: GraphEdge[];
}

/**
 * Envia o "Snapshot" do turno. Fire-and-forget.
 */
export const ingestUnifiedMemory = async (payload: UnifiedIngestPayload) => {
  try {
    // Adapter: Converte o formato do Frontend (GraphEdge: source/target) 
    // para o formato da API (subject/object)
    const apiGraphData = payload.graphData.map(edge => ({
      subject: edge.source,
      relation: edge.relation,
      object: edge.target,
      properties: edge.properties
    }));

    const apiPayload = {
      ...payload,
      graphData: apiGraphData
    };

    await apiClient.post('/ingest/unified', apiPayload);
  } catch (error: any) {
    // Diferencia erro de conexão (Offline) de erro de aplicação (Bug/400/500)
    const isNetworkError = error.message && (
        error.message.includes('Failed to fetch') || 
        error.message.includes('NetworkError') ||
        error.message.includes('Falha na conexão')
    );

    if (isNetworkError) {
        console.debug("Backend offline ou inacessível. Ingestão de memória ignorada.");
    } else {
        // Se não for erro de rede, é um erro que o backend retornou (ex: 422, 500)
        console.warn("[Memory Ingest] Falha na API:", error.message || error);
    }
  }
};

/**
 * Busca memórias semânticas (ChromaDB).
 */
export const retrieveContext = async (query: string, universeId: string, userId: string): Promise<string[]> => {
  try {
    const data = await apiClient.post<{ documents: string[] }>('/query/vector', { 
        query, 
        universeId, 
        userId 
    });
    return data.documents || [];
  } catch (error) {
    return []; 
  }
};

/**
 * Busca relacionamentos no Grafo (Neo4j).
 * O Backend retorna { subject, relation, object }, precisamos mapear para { source, target } se necessário,
 * ou o tipo GraphEdge já deve ser compatível.
 */
export const retrieveGraphContext = async (entityName: string, universeId: string, userId: string): Promise<GraphEdge[]> => {
  try {
    // O endpoint retorna arestas. Assumindo que o backend retorna { subject, relation, object }.
    // Precisamos adaptar a resposta para GraphEdge (source, relation, target).
    const data = await apiClient.post<{ edges: any[] }>('/query/graph', { 
        entity: entityName, 
        universeId, 
        userId, 
        depth: 1 
    });

    if (!data.edges) return [];

    return data.edges.map((e: any) => ({
      source: e.subject || e.source,
      target: e.object || e.target,
      relation: e.relation,
      properties: e.properties
    }));
  } catch (error) {
    return [];
  }
};

import { GameState, SimulationResponse, NarrativeResponse, WorldUpdate, NPCBehaviorResponse, CharacterTemplate, GraphEdge } from "../types";
import { synthesizeNarrative, initializeGameSession } from "./agents/narrator";
import { runNPCBehaviorEngine } from "./agents/npc";
import { runAnalyst } from "./agents/analyst"; // [NEW] Unified Agent
import { investigateScene, summarizeMemory, debugSimulation } from "./agents/system";
import { resolveDialogueTags } from "./agents/dialogue";
import { ingestUnifiedMemory, UnifiedIngestPayload } from "./ragService";

// Re-export specific agent functions
export { investigateScene, summarizeMemory, debugSimulation };

// --- PHASE 1: NARRATIVE (Fast, User Facing) ---
export const generateStory = async (
  action: string, 
  currentState: GameState
): Promise<NarrativeResponse> => {
  // 1. Narrator generates story with placeholders [[DIALOGUE:...]]
  // Pass the Universe ID for RAG Context Retrieval
  const rawResponse = await synthesizeNarrative(action, currentState);

  // 2. Dialogue Agent resolves placeholders in parallel
  const finalNarrativeText = await resolveDialogueTags(rawResponse.narrative, currentState);

  // 3. RETURN immediately for UI rendering.
  return {
    ...rawResponse,
    narrative: finalNarrativeText
  };
};

// --- PHASE 2: STATE SYNCHRONIZATION (Background) ---
export const synchronizeState = async (
  action: string,
  narrative: string,
  currentState: GameState,
  narrativeResponse?: NarrativeResponse 
): Promise<{ world: WorldUpdate, npcs: NPCBehaviorResponse }> => {

  // Parallel execution: Analyst (DBs) + NPC Engine (Behavior)
  const [analystRes, npcRes] = await Promise.all([
    runAnalyst(action, narrative, currentState),
    runNPCBehaviorEngine(currentState, action, narrative)
  ]);

  const worldRes = analystRes.worldUpdate;
  const graphEdges = analystRes.graphEdges || [];
  const memoryMeta = analystRes.memoryMetadata;

  // --- TRIPLE STORE INGESTION ---
  if (currentState.userId) {

      // Calculate snapshot of inventory for logs
      let currentInventory = [...currentState.player.inventory];
      if (worldRes.inventoryUpdates?.added) {
        currentInventory.push(...worldRes.inventoryUpdates.added);
      }
      if (worldRes.inventoryUpdates?.removed) {
        currentInventory = currentInventory.filter(item => !worldRes.inventoryUpdates?.removed?.includes(item));
      }

      const payload: UnifiedIngestPayload = {
          userId: currentState.userId,
          universeId: currentState.universeId,
          turnId: currentState.history.length + 1,
          timestamp: currentState.world.time, 

          // 1. Vector (Chroma) - Enhanced with Analyst Metadata
          vectorData: {
              text: `[ACTION]: ${action}\n[RESULT]: ${narrative}`,
              type: 'turn',
              location: worldRes.newLocation,
              keywords: memoryMeta?.keywords,
              summary: memoryMeta?.summary,
              importance: memoryMeta?.importance
          },

          // 2. SQL (Logs)
          sqlData: {
              playerStatus: worldRes.playerStatus,
              inventory: currentInventory,
              worldState: {
                  location: worldRes.newLocation,
                  time: worldRes.timePassed,
                  weather: worldRes.currentWeather
              }
          },

          // 3. Graph (Neo4j)
          graphData: graphEdges
      };

      // Fire and forget
      ingestUnifiedMemory(payload);

      // Handle specific Lore Canonical Events (Important for history)
      if (narrativeResponse && narrativeResponse.canonicalEvents && narrativeResponse.canonicalEvents.length > 0) {
          narrativeResponse.canonicalEvents.forEach(event => {
             const lorePayload: UnifiedIngestPayload = {
                 ...payload,
                 vectorData: { 
                     ...payload.vectorData, 
                     text: event, 
                     type: 'lore', 
                     summary: event,
                     importance: 'critical' 
                 },
                 graphData: [] // Lore usually doesn't have immediate graph edges unless specified
             };
             ingestUnifiedMemory(lorePayload);
          });
      }
  }

  return {
    world: worldRes,
    npcs: npcRes
  };
};

export const initializeGame = async (character: CharacterTemplate, setting: string, universeId: string, universeName: string, userId: string): Promise<SimulationResponse> => {
  // 1. Narrator creates initial state, pulling RAG context from the Universe ID
  const rawResponse = await initializeGameSession(character, setting, universeId, universeName, userId);

  // 2. Resolve any initial dialogues (though less likely in intro, it supports it)
  const mockState: GameState = {
    userId: userId,
    universeId: universeId,
    player: { 
        sourceId: character.id,
        name: character.name, 
        description: character.description, 
        inventory: [], 
        status: "", 
        location: "",
        stats: {
            strength: 10,
            agility: 10,
            intelligence: 10,
            spirit: 10,
            health: 100,
            maxHealth: 100
        }
    },
    world: { time: "", weather: "", activeEvents: [], npcs: rawResponse.npcSimulation || [] },
    knowledgeBase: { characters: [], locations: [], lore: [], quests: [] },
    summary: "",
    history: []
  };

  const finalNarrativeText = await resolveDialogueTags(rawResponse.narrative, mockState);

  // --- CRITICAL: FORCE INITIAL GRAPH POPULATION ---
  // A IA pode esquecer de gerar arestas para o próprio jogador na intro.
  // Injetamos manualmente para garantir que o nó do Player seja criado no Neo4j.
  const forcedGraphUpdates: GraphEdge[] = [
    {
        source: character.name,
        relation: "IS_A",
        target: character.archetype
    },
    {
        source: character.name,
        relation: "LOCATED_AT",
        target: rawResponse.worldUpdate.newLocation || "Start"
    },
    {
        source: character.name,
        relation: "EXISTS_IN",
        target: universeName
    }
  ];

  // Merge with AI generated updates (if any from intro schema)
  const initialGraphData = [...forcedGraphUpdates, ...(rawResponse.graphUpdates || [])];

  // Ingest initial LORE if generated
  const payload: UnifiedIngestPayload = {
      userId: userId,
      universeId: universeId,
      turnId: 0,
      timestamp: rawResponse.initialTime || "Start",
      vectorData: {
          text: finalNarrativeText,
          type: 'intro',
          location: "Start",
          summary: "Início da simulação.",
          importance: "high"
      },
      sqlData: {
          playerStatus: "Healthy",
          inventory: [],
          worldState: {}
      },
      graphData: initialGraphData
  };
  ingestUnifiedMemory(payload);

  return {
    ...rawResponse,
    narrative: finalNarrativeText
  };
};

import React, { useState, useEffect } from 'react';
import { useGameEngine } from './useGameEngine';
import { usePersistence } from './usePersistence';
import { useLibrary } from './useLibrary';
import { checkBackendHealth } from '../services/ragService';
import { NavTab } from '../components/BottomNav';
import { UniverseTemplate, CharacterTemplate } from '../types';

export type ViewState = 'ADVENTURE_LAUNCHER' | 'ADVENTURE_LIST' | 'UNIVERSE_LIST' | 'UNIVERSE_CREATOR' | 'CHARACTER_LIST' | 'CHARACTER_CREATOR' | 'SETTINGS' | 'GAME';

export const useAppController = () => {
  // Auth State
  const [userId, setUserId] = useState<string | null>(null);

  const [hasApiKey, setHasApiKey] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isInvestigationMode, setIsInvestigationMode] = useState(false);
  const [currentView, setCurrentView] = useState<ViewState>('ADVENTURE_LAUNCHER');
  const [backendStatus, setBackendStatus] = useState<'checking' | 'online' | 'offline'>('checking');

  // Check for stored session on mount
  useEffect(() => {
    const storedUser = localStorage.getItem('cronos_session_user');
    if (storedUser) setUserId(storedUser);
  }, []);

  // Library & Persistence (Depende do userId)
  const { 
      universes, 
      characters, 
      adventures,
      addUniverse, 
      addCharacter, 
      restoreDefaults, 
      evolveUniverse, 
      trackCharacterUsage, 
      addAdventureRecord,
      deleteAdventureRecord,
      deleteUniverse,
      deleteCharacter
  } = useLibrary(userId || undefined);

  const { saveGameToFile, saveToSlot, loadFromSlot, hasSlot, parseSaveFile } = usePersistence();

  // Game Engine
  const { gameState, isProcessing, isSyncingState, startGame, performAction, resetGame, restoreGame } = useGameEngine(evolveUniverse);

  // --- Effects ---

  // Auto-open sidebar on game start
  useEffect(() => {
    if (gameState && currentView === 'GAME') {
      setIsSidebarOpen(true);
    }
  }, [gameState, currentView]);

  // Check Backend Health when entering Settings
  useEffect(() => {
    if (currentView === 'SETTINGS') {
      setBackendStatus('checking');
      checkBackendHealth().then(isOnline => {
        setBackendStatus(isOnline ? 'online' : 'offline');
      });
    }
  }, [currentView]);

  // --- Auth Handlers ---
  const handleLogin = (id: string) => {
      localStorage.setItem('cronos_session_user', id);
      setUserId(id);
      setCurrentView('ADVENTURE_LAUNCHER');
  };

  const handleLogout = () => {
      localStorage.removeItem('cronos_session_user');
      resetGame();
      setIsSidebarOpen(false);
      setCurrentView('ADVENTURE_LAUNCHER');
      setUserId(null);
  };

  // --- Handlers ---

  const handleFactoryReset = () => {
    localStorage.clear();
    window.location.reload();
  };

  const handleStartAdventure = (u: UniverseTemplate, c: CharacterTemplate) => {
    if (!userId) return;

    trackCharacterUsage(c.id);
    const adventureId = addAdventureRecord(u, c); // Get the ID

    const physicsBlock = u.physics && u.physics.length > 0 ? `LEIS DA REALIDADE (Imutáveis):\n${u.physics.map(p=>`- ${p}`).join('\n')}` : '';
    const truthsBlock = u.knownTruths && u.knownTruths.length > 0 ? `VERDADES DESCOBERTAS (Conhecimento Acumulado):\n${u.knownTruths.map(t=>`- ${t}`).join('\n')}` : '';
    const timelineBlock = u.chronicles && u.chronicles.length > 0 ? `CRONOLOGIA CANÔNICA DO UNIVERSO (HISTÓRICO COMPARTILHADO):\n${u.chronicles.map(t=>`[${t.year}] ${t.event}`).join('\n')}` : '';
    const legendsBlock = u.champions && u.champions.length > 0 ? `LENDAS E HERÓIS PASSADOS:\n${u.champions.map(ch => `- ${ch.characterName}: ${ch.feat} (${ch.status})`).join('\n')}` : '';
    const magicBlock = u.magicSystem ? `SISTEMA DE MAGIA/TECNOLOGIA: ${u.magicSystem}` : '';

    const structureLabel = u.structure === 'star_cluster' ? "AGLOMERADO ESTELAR (Viagem entre Planetas)" : u.structure === 'singular_world' ? "PLANETA ÚNICO/INFINITO (Viagem Regional)" : "NEXUS MULTIVERSAL";
    const navLabel = u.navigationMethod === 'interstellar_ship' ? "NAVES ESPACIAIS" : u.navigationMethod === 'magical_gate' ? "PORTAIS MÁGICOS" : "FÍSICA (Caminhada/Veículos)";

    const settingInstruction = `
    DECISÃO DO MESTRE DE JOGO NECESSÁRIA:
    O jogador não especificou um local de início.
    Com base no Arquétipo do personagem (${c.archetype}) e no Gênero do Universo (${u.genre}), escolha um local inicial dramático e apropriado.
    `;

    const fullSettingContext = `
      UNIVERSE CONTAINER: ${u.name} (${u.genre})
      ESTRUTURA FÍSICA: ${structureLabel}
      MÉTODO DE VIAGEM PREDOMINANTE: ${navLabel}
      DESCRIÇÃO DO UNIVERSO: ${u.description}
      COSMOLOGIA: ${u.cosmology || 'Desconhecida'}
      ${physicsBlock}
      ${magicBlock}
      ${truthsBlock}
      ${timelineBlock}
      ${legendsBlock}
      ---
      STARTING INSTRUCTION: ${settingInstruction}
      ---
    `;

    startGame(c, fullSettingContext, u.id, u.name, userId, adventureId);
    setCurrentView('GAME');
  };

  const handleResumeAdventure = (adventureId: string) => {
    if (hasSlot(adventureId)) {
        const savedState = loadFromSlot(adventureId);
        if (savedState) {
            restoreGame(savedState);
            setCurrentView('GAME');
        } else {
            alert("Erro ao ler dados do slot local. Tente carregar o arquivo JSON.");
        }
    } else {
        alert("Nenhum save local encontrado para esta aventura. Por favor, carregue o arquivo .JSON.");
    }
  };

  const handleLoadGame = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const loadedState = await parseSaveFile(file);
      restoreGame(loadedState);
      if(loadedState.adventureId) saveToSlot(loadedState.adventureId, loadedState);
      setCurrentView('GAME');
    } catch (err) {
      console.error(err);
      alert("Arquivo de save inválido ou corrompido.");
    }
  };

  const handleExitToHub = () => {
    resetGame();
    setCurrentView('ADVENTURE_LAUNCHER');
  };

  const handleManualSave = () => {
      saveGameToFile(gameState);
      if (gameState && gameState.adventureId) {
          saveToSlot(gameState.adventureId, gameState);
      }
  };

  const getActiveTab = (): NavTab => {
    if (currentView === 'ADVENTURE_LIST') return 'ADVENTURES';
    if (currentView === 'UNIVERSE_LIST' || currentView === 'UNIVERSE_CREATOR') return 'UNIVERSES';
    if (currentView === 'CHARACTER_LIST' || currentView === 'CHARACTER_CREATOR') return 'CHARACTERS';
    if (currentView === 'SETTINGS') return 'SETTINGS';
    return 'PLAY';
  };

  const handleTabChange = (tab: NavTab) => {
    switch (tab) {
      case 'PLAY': setCurrentView('ADVENTURE_LAUNCHER'); break;
      case 'ADVENTURES': setCurrentView('ADVENTURE_LIST'); break;
      case 'UNIVERSES': setCurrentView('UNIVERSE_LIST'); break;
      case 'CHARACTERS': setCurrentView('CHARACTER_LIST'); break;
      case 'SETTINGS': setCurrentView('SETTINGS'); break;
    }
  };

  return {
    state: {
      userId,
      hasApiKey,
      isSidebarOpen,
      isInvestigationMode,
      currentView,
      backendStatus,
      gameState,
      isProcessing,
      isSyncingState, // [NEW] Exposed for UI feedback
      universes,
      characters,
      adventures
    },
    actions: {
      setHasApiKey,
      setIsSidebarOpen,
      setIsInvestigationMode,
      setCurrentView,
      addUniverse,
      addCharacter,
      restoreDefaults,
      performAction,
      saveGame: handleManualSave,
      handleStartAdventure,
      handleResumeAdventure,
      handleLoadGame,
      handleExitToHub,
      handleTabChange,
      handleLogin,
      handleLogout,
      handleFactoryReset,
      deleteAdventureRecord,
      deleteUniverse,
      deleteCharacter
    },
    computed: {
      activeTab: getActiveTab()
    }
  };
};

import React from 'react';
import ApiKeyModal from './components/ApiKeyModal';
import LoginScreen from './components/auth/LoginScreen';

// Architecture
import { useAppController } from './hooks/useAppController';
import GameLayout from './components/layouts/GameLayout';

// Screens
import GameScreen from './components/screens/GameScreen';
import SettingsScreen from './components/screens/SettingsScreen';
import AdventureLauncher from './components/creators/AdventureLauncher';
import { UniverseList, CharacterList, AdventureList } from './components/library/LibraryViews';
import UniverseCreator from './components/creators/UniverseCreator';
import CharacterCreator from './components/creators/CharacterCreator';

function App() {
  const { state, actions, computed } = useAppController();

  if (!state.hasApiKey) {
    return <ApiKeyModal onKeySelected={() => actions.setHasApiKey(true)} />;
  }

  // Se não estiver logado, mostra tela de login
  if (!state.userId) {
      return <LoginScreen onLogin={actions.handleLogin} />;
  }

  return (
    <GameLayout
      gameState={state.gameState}
      currentView={state.currentView}
      isSidebarOpen={state.isSidebarOpen}
      activeTab={computed.activeTab}
      onToggleSidebar={() => actions.setIsSidebarOpen(!state.isSidebarOpen)}
      onReset={actions.handleExitToHub}
      onSave={actions.saveGame}
      onLoad={actions.handleLoadGame}
      onTabChange={actions.handleTabChange}
    >

      {/* --- ROUTING --- */}

      {state.currentView === 'ADVENTURE_LAUNCHER' && (
        <AdventureLauncher 
          universes={state.universes}
          characters={state.characters}
          onStartAdventure={actions.handleStartAdventure}
          onCancel={() => {}} 
        />
      )}

      {state.currentView === 'ADVENTURE_LIST' && (
        <AdventureList 
            adventures={state.adventures}
            onDelete={actions.deleteAdventureRecord}
            onLoadGame={actions.handleLoadGame} 
            onResumeAdventure={actions.handleResumeAdventure} 
        />
      )}

      {state.currentView === 'UNIVERSE_LIST' && (
        <UniverseList 
            universes={state.universes}
            onDelete={actions.deleteUniverse}
            onCreate={() => actions.setCurrentView('UNIVERSE_CREATOR')} 
        />
      )}
      {state.currentView === 'UNIVERSE_CREATOR' && (
        <UniverseCreator 
          onSave={(t) => { actions.addUniverse(t); actions.setCurrentView('UNIVERSE_LIST'); }} 
          onCancel={() => actions.setCurrentView('UNIVERSE_LIST')} 
        />
      )}

      {state.currentView === 'CHARACTER_LIST' && (
        <CharacterList 
            characters={state.characters}
            onDelete={actions.deleteCharacter}
            onCreate={() => actions.setCurrentView('CHARACTER_CREATOR')} 
        />
      )}
      {state.currentView === 'CHARACTER_CREATOR' && (
        <CharacterCreator 
          onSave={(t) => { actions.addCharacter(t); actions.setCurrentView('CHARACTER_LIST'); }} 
          onCancel={() => actions.setCurrentView('CHARACTER_LIST')}
        />
      )}

      {state.currentView === 'SETTINGS' && (
         <SettingsScreen 
            userId={state.userId}
            backendStatus={state.backendStatus}
            onRestoreDefaults={() => { if(confirm('Restaurar templates?')) { actions.restoreDefaults(); alert('Restaurado!'); window.location.reload(); } }}
            onFactoryReset={actions.handleFactoryReset}
            onLogout={actions.handleLogout}
         />
      )}

      {state.currentView === 'GAME' && (
        <GameScreen 
          gameState={state.gameState}
          isProcessing={state.isProcessing}
          isSyncingState={state.isSyncingState} // [NEW] Prop Passed
          isInvestigationMode={state.isInvestigationMode}
          onPerformAction={actions.performAction}
          onToggleMode={() => actions.setIsInvestigationMode(!state.isInvestigationMode)}
        />
      )}

    </GameLayout>
  );
}

export default App;

